CREATE TABLE "Fee" (
    "id" UUID NOT NULL,
    "amount" NUMERIC(38, 18) NOT NULL,
    CONSTRAINT "Fee_pkey" PRIMARY KEY ("id")
);

CREATE OR REPLACE FUNCTION "orderflow_ledger_is_append_only"() RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'ledger is append-only: % on % is forbidden', TG_OP, TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER "ledger_entry_append_only"
    BEFORE UPDATE OR DELETE ON "LedgerEntry"
    FOR EACH ROW EXECUTE FUNCTION "orderflow_ledger_is_append_only"();

ALTER TABLE "Account" ADD CONSTRAINT "Account_fk" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE;
